import pg from "pg";

// bigint (int8) dikembalikan pg sebagai teks. Id pesan kita jauh di bawah 2^53, jadi aman jadi Number.
pg.types.setTypeParser(20, Number);

export const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, max: 10 });

import { createClient } from "redis";

// Satu koneksi untuk perintah biasa dan publish, satu lagi khusus subscribe
// (koneksi yang sedang subscribe tidak boleh menjalankan perintah lain).
export const redis = createClient({ url: process.env.REDIS_URL });
const sub = redis.duplicate();
redis.on("error", (e) => console.error("redis:", e.message));
sub.on("error", (e) => console.error("redis sub:", e.message));
await Promise.all([redis.connect(), sub.connect()]);

// ponytail: satu channel untuk semua room; tiap instance menerima semua event.
// Pecah jadi channel per room kalau jumlah room dan pesan sudah besar.
const CHANNEL = "chat:events";
export const publish = (ev) => redis.publish(CHANNEL, JSON.stringify(ev));
export const subscribe = (fn) => sub.subscribe(CHANNEL, (raw) => fn(JSON.parse(raw)));
export const closeBus = () => Promise.all([redis.close(), sub.close()]);

import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.TOKEN_SECRET;
if (!SECRET || SECRET.length < 32) throw new Error("TOKEN_SECRET wajib diisi, minimal 32 karakter");

const sign = (data) => createHmac("sha256", SECRET).update(data).digest("base64url");

// Token = base64url(payload) + "." + tanda tangan HMAC. Mirip JWT, tanpa dependensi.
export function issueToken(user, ttlSec = 3600) {
  const exp = Math.floor(Date.now() / 1000) + ttlSec;
  const data = Buffer.from(JSON.stringify({ user, exp })).toString("base64url");
  return `${data}.${sign(data)}`;
}

// Mengembalikan nama pengguna kalau token sah dan belum kedaluwarsa, selain itu null.
export function verifyToken(token) {
  const [data, sig] = String(token ?? "").split(".");
  if (!data || !sig) return null;
  const a = Buffer.from(sig);
  const b = Buffer.from(sign(data));
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  const { user, exp } = JSON.parse(Buffer.from(data, "base64url").toString());
  return exp > Date.now() / 1000 ? user : null;
}

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { hostname } from "node:os";
import { WebSocketServer } from "ws";
import { issueToken, verifyToken } from "./token.js";
import { onConnection, startHub } from "./hub.js";

const PORT = Number(process.env.PORT ?? 3000);
const INSTANCE = process.env.INSTANCE_NAME ?? hostname();
const ORIGINS = (process.env.ALLOWED_ORIGINS ?? "").split(",").filter(Boolean);
const NAME = /^[a-zA-Z0-9_]{2,20}$/;
const page = await readFile(new URL("../public/index.html", import.meta.url));

function json(res, status, body) {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

const server = createServer(async (req, res) => {
  if (req.method === "GET" && req.url === "/") {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    return res.end(page);
  }
  if (req.method === "GET" && req.url === "/health") return json(res, 200, { status: "ok", instance: INSTANCE });
  if (req.method === "POST" && req.url === "/token") {
    // DEMO: siapa pun bisa meminta token untuk nama apa pun. Di aplikasi sungguhan,
    // token baru diterbitkan setelah login (sesi atau kata sandi) berhasil.
    let body = "";
    for await (const chunk of req) {
      body += chunk;
      if (body.length > 1000) return json(res, 413, { error: "body terlalu besar" });
    }
    let name;
    try { name = JSON.parse(body).name; } catch {}
    if (typeof name !== "string" || !NAME.test(name)) return json(res, 400, { error: "nama 2-20 huruf, angka, atau _" });
    return json(res, 200, { token: issueToken(name) });
  }
  json(res, 404, { error: "tidak ditemukan" });
});

// maxPayload: frame lebih besar dari 4 KB langsung ditutup oleh ws dengan kode 1009.
const wss = new WebSocketServer({ noServer: true, maxPayload: 4096 });

server.on("upgrade", (req, socket, head) => {
  socket.on("error", console.error);
  const url = new URL(req.url, "http://localhost");
  // Browser tidak bisa memasang header Authorization di WebSocket, jadi token dikirim lewat query.
  const user = url.pathname === "/ws" ? verifyToken(url.searchParams.get("token")) : null;
  const originOk = ORIGINS.length === 0 || ORIGINS.includes(req.headers.origin);
  if (!user || !originOk) {
    socket.write("HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n");
    return socket.destroy();
  }
  socket.removeListener("error", console.error);
  wss.handleUpgrade(req, socket, head, (ws) => wss.emit("connection", ws, user));
});

// Koneksi yang diam-diam putus (HP masuk terowongan) tidak memicu close. Ping tiap 30 detik membersihkannya.
wss.on("connection", (ws, user) => {
  ws.isAlive = true;
  ws.on("pong", () => { ws.isAlive = true; });
  onConnection(ws, user);
});
const heartbeat = setInterval(() => {
  for (const ws of wss.clients) {
    if (!ws.isAlive) { ws.terminate(); continue; }
    ws.isAlive = false;
    ws.ping();
  }
}, 30_000);

// Saat deploy, instance lama dimatikan dengan SIGTERM. Tutup dengan 1012 supaya klien langsung reconnect.
process.on("SIGTERM", () => {
  clearInterval(heartbeat);
  for (const ws of wss.clients) ws.close(1012, "server restart");
  server.close();
  setTimeout(() => process.exit(0), 2000);
});

await startHub();
server.listen(PORT, () => console.log(`[${INSTANCE}] siap di http://localhost:${PORT}`));

