// Semua event dari klien lewat sini dulu. Tidak ada yang dipercaya sebelum lolos.
export const VERSION = 1;
export const MAX_TEXT = 1000;
const ROOM = /^[a-z0-9-]{1,32}$/;
const CID = /^[A-Za-z0-9-]{8,64}$/;
const isId = (n) => Number.isSafeInteger(n) && n >= 0;

export function parseClientEvent(raw) {
  let ev;
  try {
    ev = JSON.parse(raw);
  } catch {
    return { error: "bad_json" };
  }
  if (ev === null || typeof ev !== "object") return { error: "bad_json" };
  if (ev.v !== VERSION) return { error: "bad_version" };
  if (typeof ev.room !== "string" || !ROOM.test(ev.room)) return { error: "bad_room" };
  const { type, room } = ev;

  switch (type) {
    case "join":
      if (ev.after !== undefined && !isId(ev.after)) return { error: "bad_cursor" };
      return { type, room, after: ev.after };
    case "leave":
    case "typing":
      return { type, room };
    case "send": {
      if (typeof ev.cid !== "string" || !CID.test(ev.cid)) return { error: "bad_cid" };
      const text = typeof ev.text === "string" ? ev.text.trim() : "";
      if (!text || text.length > MAX_TEXT) return { error: "bad_text", cid: ev.cid };
      return { type, room, cid: ev.cid, text };
    }
    case "history":
      if (!isId(ev.before)) return { error: "bad_cursor" };
      return { type, room, before: ev.before };
    default:
      return { error: "bad_type" };
  }
}

// Token bucket: rate token per detik, maksimal burst token tersimpan.
export function tokenBucket(rate, burst) {
  let tokens = burst;
  let last = Date.now();
  return () => {
    const now = Date.now();
    tokens = Math.min(burst, tokens + ((now - last) / 1000) * rate);
    last = now;
    if (tokens < 1) return false;
    tokens -= 1;
    return true;
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { parseClientEvent, tokenBucket } from "../src/protocol.js";

const p = (o) => parseClientEvent(JSON.stringify(o));

test("event sah diterima", () => {
  assert.deepEqual(p({ v: 1, type: "join", room: "umum" }), { type: "join", room: "umum", after: undefined });
  assert.deepEqual(p({ v: 1, type: "send", room: "umum", cid: "abc12345", text: "  halo " }),
    { type: "send", room: "umum", cid: "abc12345", text: "halo" });
});

test("event rusak ditolak", () => {
  assert.equal(parseClientEvent("{bukan json").error, "bad_json");
  assert.equal(parseClientEvent("null").error, "bad_json");
  assert.equal(p({ v: 2, type: "join", room: "umum" }).error, "bad_version");
  assert.equal(p({ v: 1, type: "join", room: "Umum Besar" }).error, "bad_room");
  assert.equal(p({ v: 1, type: "send", room: "umum", cid: "abc12345", text: "   " }).error, "bad_text");
  assert.equal(p({ v: 1, type: "send", room: "umum", cid: "abc12345", text: "x".repeat(1001) }).error, "bad_text");
  assert.equal(p({ v: 1, type: "history", room: "umum", before: -1 }).error, "bad_cursor");
  assert.equal(p({ v: 1, type: "hapus", room: "umum" }).error, "bad_type");
});

test("token bucket menolak setelah burst habis", () => {
  const allow = tokenBucket(1, 3);
  assert.deepEqual([allow(), allow(), allow(), allow()], [true, true, true, false]);
});

import { redis } from "./bus.js";

// Presence = sorted set per room: anggota = nama pengguna, skor = waktu terakhir terlihat.
// Instance yang mati berhenti memperbarui skor, jadi penggunanya hilang sendiri setelah TTL.
const TTL = 30_000;
const key = (room) => `presence:${room}`;

export const touch = (room, user) => redis.zAdd(key(room), { score: Date.now(), value: user });
export const remove = (room, user) => redis.zRem(key(room), user);

export async function list(room) {
  await redis.zRemRangeByScore(key(room), 0, Date.now() - TTL);
  return redis.zRange(key(room), 0, -1);
}

import { pool } from "./db.js";
import { publish, subscribe } from "./bus.js";
import { VERSION, parseClientEvent, tokenBucket } from "./protocol.js";
import * as presence from "./presence.js";

const MAX_ROOMS = 10;
const PAGE = 50;
const RESUME_LIMIT = 200;
const COLS = `id, room, user_name as "user", cid, body as text, created_at as ts`;

// room -> Set<ws>, hanya koneksi di instance ini. Instance lain punya Map sendiri.
const rooms = new Map();

function send(ws, ev) {
  if (ws.readyState === ws.OPEN) ws.send(JSON.stringify({ v: VERSION, ...ev }));
}

// Semua event yang perlu sampai ke banyak orang lewat Redis, termasuk ke instance ini sendiri.
function deliver(ev) {
  for (const ws of rooms.get(ev.room) ?? []) {
    if (ev.type === "typing" && ws.user === ev.user) continue;
    send(ws, ev);
  }
}

async function broadcastPresence(room) {
  await publish({ type: "presence", room, members: await presence.list(room) });
}

const handlers = {
  async join(ws, { room, after }) {
    if (!ws.rooms.has(room) && ws.rooms.size >= MAX_ROOMS) {
      return send(ws, { type: "error", code: "too_many_rooms", room });
    }
    if (!rooms.has(room)) rooms.set(room, new Set());
    rooms.get(room).add(ws);
    ws.rooms.add(room);
    await presence.touch(room, ws.user);

    // Koneksi sudah terdaftar di room SEBELUM query, jadi tidak ada pesan yang jatuh di celah.
    // Akibatnya satu pesan bisa datang dua kali (live dan dari query): klien membuang duplikat berdasarkan id.
    const { rows } = after === undefined
      ? await pool.query(
          `select * from (select ${COLS} from messages where room = $1 order by id desc limit $2) t order by id`,
          [room, PAGE])
      : await pool.query(
          `select ${COLS} from messages where room = $1 and id > $2 order by id limit $3`,
          [room, after, RESUME_LIMIT]);
    send(ws, { type: "joined", room, messages: rows, more: after === undefined && rows.length === PAGE });
    await broadcastPresence(room);
  },

  async leave(ws, { room }) {
    await leaveRoom(ws, room);
  },

  async send(ws, { room, cid, text }) {
    if (!ws.rooms.has(room)) return send(ws, { type: "error", code: "not_in_room", room, cid });
    // cid unik per pengguna: kalau klien mengirim ulang setelah reconnect, pesan tidak tersimpan dua kali.
    const ins = await pool.query(
      `insert into messages (room, user_name, cid, body) values ($1, $2, $3, $4)
       on conflict (user_name, cid) do nothing returning ${COLS}`,
      [room, ws.user, cid, text]);
    const msg = ins.rows[0]
      ?? (await pool.query(`select ${COLS} from messages where user_name = $1 and cid = $2`, [ws.user, cid])).rows[0];
    send(ws, { type: "ack", room, cid, id: msg.id });
    if (ins.rows[0]) await publish({ type: "message", ...msg });
  },

  async history(ws, { room, before }) {
    if (!ws.rooms.has(room)) return send(ws, { type: "error", code: "not_in_room", room });
    const { rows } = await pool.query(
      `select ${COLS} from messages where room = $1 and id < $2 order by id desc limit $3`,
      [room, before, PAGE]);
    send(ws, { type: "history", room, messages: rows.reverse(), more: rows.length === PAGE });
  },

  async typing(ws, { room }) {
    if (ws.rooms.has(room)) await publish({ type: "typing", room, user: ws.user });
  },
};

async function leaveRoom(ws, room) {
  if (!ws.rooms.delete(room)) return;
  const set = rooms.get(room);
  set.delete(ws);
  if (set.size === 0) rooms.delete(room);
  // Pengguna yang sama mungkin masih membuka tab lain di instance ini.
  // ponytail: tab di instance LAIN tidak terlihat dari sini; heartbeat-nya mengembalikan nama itu dalam <=10 detik.
  if (![...set].some((other) => other.user === ws.user)) {
    await presence.remove(room, ws.user);
  }
  await broadcastPresence(room);
}

export function onConnection(ws, user) {
  ws.user = user;
  ws.rooms = new Set();
  const allow = tokenBucket(5, 10);
  let strikes = 0;
  send(ws, { type: "hello", user });

  ws.on("message", async (raw, isBinary) => {
    if (!allow()) {
      send(ws, { type: "error", code: "rate_limited" });
      if (++strikes > 20) ws.close(1008, "rate limit");
      return;
    }
    const ev = isBinary ? { error: "bad_json" } : parseClientEvent(raw.toString());
    if (ev.error) return send(ws, { type: "error", code: ev.error, cid: ev.cid });
    try {
      await handlers[ev.type](ws, ev);
    } catch (err) {
      console.error(err);
      send(ws, { type: "error", code: "server_error", cid: ev.cid });
    }
  });

  // Tanpa listener ini, frame kebesaran (ws menutupnya dengan 1009) melempar 'error' dan mematikan proses.
  ws.on("error", (err) => console.warn(`ws ${user}:`, err.message));

  ws.on("close", async () => {
    for (const room of [...ws.rooms]) await leaveRoom(ws, room).catch(console.error);
  });
}

export async function startHub() {
  await subscribe(deliver);
  // Perbarui "terakhir terlihat" semua pengguna yang tersambung ke instance ini.
  setInterval(() => {
    for (const [room, set] of rooms) {
      for (const user of new Set([...set].map((ws) => ws.user))) presence.touch(room, user).catch(console.error);
    }
  }, 10_000).unref();
}

