// Uji dua instance: node scripts/smoke.js http://localhost:3001 http://localhost:3002
import assert from "node:assert/strict";
import WebSocket from "ws";

const [URL_A = "http://localhost:3001", URL_B = "http://localhost:3002"] = process.argv.slice(2);
const ROOM = `uji-${Date.now()}`;

async function token(base, name) {
  const res = await fetch(`${base}/token`, { method: "POST", body: JSON.stringify({ name }) });
  return (await res.json()).token;
}

async function client(base, name) {
  const ws = new WebSocket(`${base.replace(/^http/, "ws")}/ws?token=${await token(base, name)}`);
  const inbox = [];
  ws.on("message", (d) => inbox.push(JSON.parse(d)));
  // Tunggu event pertama yang cocok, lalu buang dari inbox.
  const wait = (match, ms = 3000) => new Promise((resolve, reject) => {
    const start = Date.now();
    const timer = setInterval(() => {
      const i = inbox.findIndex(match);
      if (i >= 0) { clearInterval(timer); resolve(inbox.splice(i, 1)[0]); }
      else if (Date.now() - start > ms) { clearInterval(timer); reject(new Error(`timeout: ${match}`)); }
    }, 10);
  });
  const send = (ev) => ws.send(JSON.stringify({ v: 1, ...ev }));
  await new Promise((resolve, reject) => { ws.once("open", resolve); ws.once("error", reject); });
  await wait((e) => e.type === "hello");
  return { ws, wait, send };
}

// 1. Tanpa token sah, upgrade ditolak.
const status = await new Promise((resolve) => {
  const ws = new WebSocket(`${URL_A.replace(/^http/, "ws")}/ws?token=palsu.palsu`);
  ws.on("unexpected-response", (_req, res) => resolve(res.statusCode));
  ws.on("error", () => {});
});
assert.equal(status, 401);

// 2. Pesan dari instance A sampai ke pengguna di instance B (lewat Redis).
const ani = await client(URL_A, "ani");
const budi = await client(URL_B, "budi");
ani.send({ type: "join", room: ROOM });
await ani.wait((e) => e.type === "joined");
budi.send({ type: "join", room: ROOM });
await budi.wait((e) => e.type === "joined");
await ani.wait((e) => e.type === "presence" && e.members.length === 2);

ani.send({ type: "send", room: ROOM, cid: "smoke-0001", text: "halo dari A" });
const ack = await ani.wait((e) => e.type === "ack");
const got = await budi.wait((e) => e.type === "message");
assert.equal(got.text, "halo dari A");
assert.equal(got.id, ack.id);

// 3. Kirim ulang cid yang sama: id sama, tidak ada pesan ganda.
ani.send({ type: "send", room: ROOM, cid: "smoke-0001", text: "halo dari A" });
assert.equal((await ani.wait((e) => e.type === "ack")).id, ack.id);
await assert.rejects(budi.wait((e) => e.type === "message", 500));

// 4. Typing lintas instance.
budi.send({ type: "typing", room: ROOM });
assert.equal((await ani.wait((e) => e.type === "typing")).user, "budi");

// 5. Budi putus, dua pesan terlewat, reconnect ke instance A dan mengejar ketinggalan.
budi.ws.close();
await ani.wait((e) => e.type === "presence" && e.members.length === 1);
for (const n of [2, 3]) {
  ani.send({ type: "send", room: ROOM, cid: `smoke-000${n}`, text: `pesan ${n}` });
  await ani.wait((e) => e.type === "ack");
}
const budi2 = await client(URL_A, "budi");
budi2.send({ type: "join", room: ROOM, after: got.id });
const joined = await budi2.wait((e) => e.type === "joined");
assert.deepEqual(joined.messages.map((m) => m.text), ["pesan 2", "pesan 3"]);

// 6. Riwayat lebih lama lewat cursor.
budi2.send({ type: "history", room: ROOM, before: joined.messages[0].id });
assert.deepEqual((await budi2.wait((e) => e.type === "history")).messages.map((m) => m.text), ["halo dari A"]);

// 7. Frame lebih dari 4 KB ditutup dengan kode 1009, server tetap hidup.
const big = await client(URL_B, "cici");
const code = await new Promise((resolve) => { big.ws.on("close", resolve); big.ws.send("x".repeat(5000)); });
assert.equal(code, 1009);
assert.equal((await fetch(`${URL_B}/health`)).status, 200);

ani.ws.close();
budi2.ws.close();
console.log("SEMUA LULUS");

// Uji beban kecil: node scripts/load.js <jumlah-klien> <pesan-per-klien> URL1 URL2 ...
// Contoh: node scripts/load.js 200 20 http://localhost:3001 http://localhost:3002
import WebSocket from "ws";

const [clients = "100", perClient = "20", ...urls] = process.argv.slice(2);
const N = Number(clients), M = Number(perClient);
const bases = urls.length ? urls : ["http://localhost:3001", "http://localhost:3002"];
const ROOM = `beban-${Date.now()}`;
const sentAt = new Map();   // cid -> waktu kirim
const latencies = [];
let received = 0, errors = 0;

async function connect(i) {
  const base = bases[i % bases.length];   // bagi rata ke semua instance
  const res = await fetch(`${base}/token`, { method: "POST", body: JSON.stringify({ name: `bot${i}` }) });
  const { token } = await res.json();
  const ws = new WebSocket(`${base.replace(/^http/, "ws")}/ws?token=${token}`);
  ws.on("message", (raw) => {
    const ev = JSON.parse(raw);
    if (ev.type === "message") {
      received++;
      // Latensi diukur saat pesan kembali ke pengirimnya sendiri (sudah lewat Postgres dan Redis).
      if (ev.user === `bot${i}` && sentAt.has(ev.cid)) latencies.push(performance.now() - sentAt.get(ev.cid));
    }
    if (ev.type === "error") errors++;
  });
  await new Promise((resolve, reject) => { ws.once("open", resolve); ws.once("error", reject); });
  ws.send(JSON.stringify({ v: 1, type: "join", room: ROOM }));
  return ws;
}

const sockets = [];
for (let i = 0; i < N; i++) sockets.push(await connect(i));
console.log(`${N} klien tersambung ke ${bases.length} instance`);
await new Promise((r) => setTimeout(r, 1000));

// Tiap klien mengirim 2 pesan per detik, di bawah batas rate limit server (5 per detik).
const t0 = performance.now();
await Promise.all(sockets.map(async (ws, i) => {
  for (let k = 0; k < M; k++) {
    const cid = `bot${i}-${k}-${t0.toFixed(0)}`;
    sentAt.set(cid, performance.now());
    ws.send(JSON.stringify({ v: 1, type: "send", room: ROOM, cid, text: `pesan ${k}` }));
    await new Promise((r) => setTimeout(r, 500));
  }
}));
await new Promise((r) => setTimeout(r, 3000));   // beri waktu pesan terakhir sampai

const sorted = latencies.sort((a, b) => a - b);
const pct = (p) => sorted[Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length))]?.toFixed(1);
const expected = N * M * N;   // tiap pesan sampai ke semua N klien
console.log({
  durasi_detik: ((performance.now() - t0) / 1000).toFixed(1),
  pesan_terkirim: N * M,
  pengiriman_diterima: `${received} dari ${expected}`,
  error: errors,
  latensi_ms: { p50: pct(50), p95: pct(95), p99: pct(99) },
});
for (const ws of sockets) ws.close();
